from math import sqrt

def briggs(a, n):
    x = a
    for k in range(n):
        x = sqrt(x)              # n racines carrées successives
    return 2 ** n * (x - 1)      # ln(a) ≈ 2^n × (x - 1)

print(briggs(2, 10))   # environ 0.69338
print(briggs(2, 20))   # environ 0.693147
